import {CanvasSurface} from './field.js';
const colors=['#4bccff','#7b8dff','#c18aff','#f381e9','#ff8f83','#ffd77a','#ffffff'];
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const hash=s=>{let n=0;for(const c of String(s))n=(Math.imul(n,31)+c.charCodeAt(0))>>>0;return n};
const time=e=>new Date(e.timestamp).getTime();
const short=n=>n.name.replace('Researcher ','R').replace('Orchestrator','ORCH').replace('Synthesizer','SYNTH').replace('Librarian','LIB');

export class EventInstruments{
  constructor(getEngine,{onAgent=()=>{}}={}){this.getEngine=getEngine;this.onAgent=onAgent;this.views={};this.hits={};this.version=-1;this.now=Date.now();this.model=null;
    for(const kind of ['tasks','agents','metrics']){const panel=document.querySelector(`.${kind}-panel`),canvas=document.createElement('canvas');canvas.className=`event-instrument instrument-${kind}`;canvas.setAttribute('aria-label',({tasks:'Actual tool execution spans by agent. Hover for durations and token counts.',agents:'Agent handoff matrix: each cell counts real source-to-target messages.',metrics:'Latency and token consumption plotted from actual event timestamps.'})[kind]);panel.append(canvas);this.views[kind]=new CanvasSurface(canvas);const tip=document.createElement('div');tip.className='instrument-tooltip';tip.hidden=true;panel.append(tip);
      canvas.addEventListener('pointermove',event=>{const r=canvas.getBoundingClientRect(),x=event.clientX-r.left,y=event.clientY-r.top,hit=(this.hits[kind]??[]).find(a=>x>=a.x&&x<=a.x+a.w&&y>=a.y&&y<=a.y+a.h);canvas.style.cursor=hit?'pointer':'default';tip.hidden=!hit;if(hit){tip.textContent=hit.label;tip.style.left=`${clamp(x,0,panel.clientWidth-180)}px`;tip.style.top=`${Math.max(0,y-45)}px`}});canvas.addEventListener('pointerleave',()=>tip.hidden=true);canvas.addEventListener('click',event=>{const r=canvas.getBoundingClientRect(),x=event.clientX-r.left,y=event.clientY-r.top,hit=(this.hits[kind]??[]).find(a=>x>=a.x&&x<=a.x+a.w&&y>=a.y&&y<=a.y+a.h);if(hit?.agent)this.onAgent(hit.agent)})
    }
  }
  step(){}
  build(e){const agents=[...e.nodes.values()].filter(n=>n.kind==='agent').slice(0,8),events=e.events.slice().sort((a,b)=>time(a)-time(b)),open=new Map(),spans=[];
    for(const event of events){const key=event.agentId+'|'+event.tool,stamp=time(event);if(event.type==='tool_call'){if(['success','complete'].includes(event.status)){spans.push({event,start:stamp,end:stamp+event.latencyMs,active:false,tokens:event.tokens})}else{if(!open.has(key))open.set(key,[]);open.get(key).push(event)}}else if(event.type==='tool_result'){const call=open.get(key)?.shift();spans.push({event,start:call?time(call):stamp-event.latencyMs,end:stamp,active:false,tokens:event.tokens})}}
    for(const list of open.values())for(const event of list)spans.push({event,start:time(event),end:null,active:true,tokens:event.tokens});this.model={agents,events,spans};this.version=e.version;
  }
  draw(){const e=this.getEngine();if(!e)return;if(!e.paused)this.now=Date.now();if(e.version!==this.version||!this.model)this.build(e);for(const [kind,view]of Object.entries(this.views)){if(view.canvas.closest('.panel').hidden||!view.width||!view.height||!view.ctx)continue;view.ctx.clearRect(0,0,view.width,view.height);this.hits[kind]=[];this[kind](view.ctx,view.width,view.height,e)}}
  tasks(c,w,h,e){const {agents,spans}=this.model,window=15000,start=this.now-window,left=Math.min(59,w*.22),top=18,bottom=h-19,plot=w-left-6,row=(bottom-top)/Math.max(1,agents.length);c.font='8px Segoe UI,Arial,sans-serif';c.fillStyle='#fff';c.fillText('TOOL EXECUTION / 15s',0,9);c.textAlign='right';c.fillText(`${spans.filter(s=>s.active&&s.start>=start).length} OPEN`,w-2,9);c.textAlign='left';
    for(let i=0;i<=3;i++){const x=left+i/3*plot;c.strokeStyle='#ffffff';c.globalAlpha=.2;c.lineWidth=.5;c.beginPath();c.moveTo(x,top-2);c.lineTo(x,bottom);c.stroke();c.globalAlpha=1;c.fillStyle='#fff';c.fillText(i===3?'NOW':`−${15-i*5}s`,Math.min(w-23,x-3),h-4)}
    agents.forEach((agent,i)=>{const y=top+row*i;c.globalAlpha=.15;c.strokeStyle='#fff';c.beginPath();c.moveTo(left,y+row-1);c.lineTo(w,y+row-1);c.stroke();c.globalAlpha=1;c.fillStyle='#fff';c.font='8px Segoe UI,Arial,sans-serif';c.fillText(short(agent).slice(0,8),0,y+row*.6)});
    for(const span of spans){const index=agents.findIndex(a=>a.id===span.event.agentId);if(index<0)continue;const end=span.active?this.now:span.end;if(end<start||span.start>this.now)continue;const x=left+clamp((span.start-start)/window,0,1)*plot,x2=left+clamp((end-start)/window,0,1)*plot,y=top+index*row+row*.2,width=Math.max(2,x2-x),height=Math.max(3,row*.56),fresh=this.now-time(span.event)<600;
      c.globalAlpha=1;c.fillStyle=fresh||span.active?colors[hash(span.event.tool)%colors.length]:'#fff';if(span.active){c.strokeStyle=c.fillStyle;c.lineWidth=.8;c.strokeRect(x,y,width,height);c.fillRect(x2-1,y-1,2,height+2)}else c.fillRect(x,y,width,height);if(width>38){c.fillStyle='#050508';c.font='7px Segoe UI,Arial,sans-serif';c.fillText(span.event.tool.slice(0,12),x+3,y+height-2)}this.hits.tasks.push({x,y,w:Math.max(width,5),h:height,label:`${span.event.agentName} / ${span.event.tool}\n${Math.round(end-span.start)} ms · ${span.tokens} tokens${span.active?' · awaiting result':''}`,agent:span.event.agentId})
    }c.globalAlpha=1;
  }
  agents(c,w,h,e){const {agents,events}=this.model,n=agents.length;if(!n)return;const count=Array.from({length:n},()=>Array.from({length:n},()=>({count:0,tokens:0,last:0}))),cutoff=this.now-30000;
    for(const event of events){if(!event.targetAgent||time(event)<cutoff)continue;const a=agents.findIndex(n=>n.id===event.agentId),b=agents.findIndex(n=>n.id===event.targetAgent);if(a<0||b<0)continue;count[a][b].count+=event._count??1;count[a][b].tokens+=event.tokens;count[a][b].last=Math.max(count[a][b].last,time(event))}
    const left=14,top=22,size=Math.max(6,Math.min((w-left-3)/n,(h-top-10)/n)),max=Math.max(1,...count.flat().map(a=>a.count));c.fillStyle='#fff';c.font='8px Segoe UI,Arial,sans-serif';c.fillText('HANDOFFS / 30s',2,9);
    for(let i=0;i<n;i++){c.fillText(String(i+1),left+i*size+size*.35,top-4);c.fillText(String(i+1),2,top+i*size+size*.65);for(let j=0;j<n;j++){const cell=count[i][j],x=left+j*size,y=top+i*size,active=this.now-cell.last<700;c.globalAlpha=cell.count?.25+.65*cell.count/max:.12;c.strokeStyle='#fff';c.lineWidth=.5;c.strokeRect(x+1,y+1,size-2,size-2);if(cell.count){c.fillStyle=active?colors[(i+j)%colors.length]:'#fff';c.globalAlpha=active?.9:.12+.42*cell.count/max;c.fillRect(x+2,y+2,size-4,size-4);c.globalAlpha=1;c.fillStyle='#fff';c.font=`${size>15?8:6}px Segoe UI,Arial,sans-serif`;c.textAlign='center';c.fillText(String(cell.count),x+size*.5,y+size*.67);c.textAlign='left'}this.hits.agents.push({x,y,w:size,h:size,label:`${agents[i].name} → ${agents[j].name}\n${cell.count} handoffs · ${cell.tokens} tokens / 30s`,agent:agents[i].id})}}
    c.globalAlpha=1;
  }
  metrics(c,w,h,e){const start=this.now-15000,events=this.model.events.filter(a=>time(a)>=start&&time(a)<=this.now),latency=events.filter(a=>a.latencyMs>0),maxLatency=Math.max(200,...latency.map(a=>a.latencyMs)),top=12,middle=h*.55,bottom=h-13,left=5,right=w-5,plot=right-left;
    c.font='8px Segoe UI,Arial,sans-serif';c.fillStyle='#fff';c.fillText('LATENCY / EVENT',left,8);c.textAlign='right';c.fillText(`${Math.round(maxLatency)} ms`,right,8);c.textAlign='left';for(const y of [top,middle-8,bottom]){c.globalAlpha=.25;c.strokeStyle='#fff';c.lineWidth=.5;c.beginPath();c.moveTo(left,y);c.lineTo(right,y);c.stroke()}c.globalAlpha=1;
    const points=latency.map(a=>({event:a,x:left+(time(a)-start)/15000*plot,y:middle-10-a.latencyMs/maxLatency*(middle-top-16)}));c.beginPath();points.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.strokeStyle='#fff';c.lineWidth=.8;c.globalAlpha=.8;c.stroke();c.globalAlpha=1;
    for(const p of points){const fresh=this.now-time(p.event)<500,r=1.5+Math.min(2.3,Math.sqrt(p.event.tokens/800));c.fillStyle=fresh?colors[hash(p.event.eventId)%colors.length]:'#fff';c.beginPath();c.arc(p.x,p.y,r,0,Math.PI*2);c.fill();this.hits.metrics.push({x:p.x-4,y:p.y-4,w:8,h:8,label:`${p.event.tool||p.event.agentName}\n${p.event.latencyMs} ms · ${p.event.tokens} tokens`,agent:p.event.agentId})}
    const buckets=Array.from({length:15},()=>[0,0]);for(const event of events){const idx=clamp(Math.floor((time(event)-start)/1000),0,14),output=['tool_result','output','message'].includes(event.type);buckets[idx][output?1:0]+=event.tokens}const max=Math.max(1,...buckets.map(a=>a[0]+a[1])),bar=plot/15;c.font='8px Segoe UI,Arial,sans-serif';c.fillStyle='#fff';c.fillText('TOKENS / SECOND',left,middle+4);
    buckets.forEach((b,i)=>{const x=left+i*bar+1,height=(b[0]+b[1])/max*(bottom-middle-11),y=bottom-height;c.globalAlpha=1;c.strokeStyle='#fff';c.lineWidth=.65;c.strokeRect(x,y,Math.max(1,bar-3),height);if(b[1]){c.fillStyle=i===14?colors[hash(events.at(-1)?.eventId??'')%colors.length]:'#fff';const oh=b[1]/max*(bottom-middle-11);c.fillRect(x+1,bottom-oh,Math.max(1,bar-5),oh)}this.hits.metrics.push({x,y:middle+8,w:bar,h:bottom-middle-8,label:`${15-i}s ago · input ${b[0]} / output ${b[1]} tokens`})});c.fillStyle='#fff';c.fillText('−15s',left,h-2);c.textAlign='right';c.fillText('NOW',right,h-2);c.textAlign='left';c.globalAlpha=1;
  }
}
